"""Administrator presentation only. No SQL, permissions or session changes."""
from html import escape
from .theme import stylesheet_html
from .icons import icon_container

ADMIN_CSS = '<style>\n.st-key-bui_admin_surface{--admin-navy:#173052;--admin-magenta:#DF73A0;color:#173052;background:#F6F8FC;padding:clamp(12px,2vw,24px);border-radius:24px;border:1px solid #E6EAF2;min-width:0;}\n.st-key-bui_admin_surface .bui-admin-header{background:white;border-left:5px solid #8462C3;border-radius:18px;padding:24px;margin-bottom:24px;box-shadow:0 5px 18px rgba(23,48,82,.06);}\n.st-key-bui_admin_surface .bui-admin-header h1{color:#173052;font-size:clamp(24px,3vw,36px);line-height:1.25;margin:16px 0;}\n.st-key-bui_admin_surface .bui-admin-header p{color:#526175;}\n.st-key-bui_admin_surface .bui-admin-logo{display:block;width:min(280px,100%);height:auto;}\n.st-key-bui_admin_surface :is(.teacher-card,.metric){background:#fff!important;color:#173052!important;border:1px solid #E6EAF2!important;border-left:5px solid #8462C3!important;border-radius:18px!important;padding:20px!important;box-shadow:0 5px 18px rgba(23,48,82,.06)!important;margin-bottom:16px;overflow-wrap:anywhere;}\n.st-key-bui_admin_surface .metric{border-left-color:#33836A!important;min-height:110px;}\n.st-key-bui_admin_surface .metric b{font-size:28px;color:#173052;}\n.st-key-bui_admin_surface :is(.teacher-card h3,.teacher-card p,.metric span){color:#173052!important;}\n.st-key-bui_admin_surface .teacher-card .small{color:#526175!important;}\n.st-key-bui_admin_surface [data-testid="stExpander"]{background:white;border-radius:12px;border-left:4px solid #D6A12D;}\n.st-key-bui_admin_surface [data-testid="stButton"] button{min-height:44px;color:#173052;border-radius:10px;border:1px solid #173052;}\n.st-key-bui_admin_surface [data-testid="stButton"] button[kind="primary"]{background:#DF73A0!important;color:#102642!important;}\n.st-key-bui_admin_surface [data-testid] :is(button,input,[role="combobox"],summary):focus-visible{outline:3px solid #173052!important;outline-style:solid!important;outline-offset:3px;}\n.st-key-bui_admin_surface :is([data-testid="stPlotlyChart"],[data-testid="stDataFrame"]){max-width:100%;}\n.st-key-bui_admin_surface [data-testid="stHorizontalBlock"]{min-width:0;}\n\n.st-key-bui_admin_surface [data-testid="stHorizontalBlock"]{flex-wrap:wrap!important;}\n.st-key-bui_admin_surface [data-testid="stColumn"]{flex:1 1 180px!important;min-width:0!important;}\nbody:has(.st-key-bui_admin_surface) [data-testid="stSidebar"]{background:#F6F8FC;}\nbody:has(.st-key-bui_admin_surface) [data-testid="stSidebar"] button{min-height:44px;color:#173052;border-radius:10px;}\nbody:has(.st-key-bui_admin_surface) [data-testid="stSidebar"] button[kind="primary"]{background:#DF73A0!important;color:#102642!important;border-color:#173052!important;}\nbody:has(.st-key-bui_admin_surface) [data-testid="stSidebar"] button:focus-visible{outline:3px solid #173052!important;outline-style:solid!important;outline-offset:3px;}\n@media(max-width:768px){.st-key-bui_admin_surface [data-testid="stHorizontalBlock"]{flex-wrap:wrap!important;}.st-key-bui_admin_surface [data-testid="stColumn"]{width:100%!important;flex:1 1 100%!important;min-width:0!important;}.st-key-bui_admin_surface .bui-admin-header{padding:16px;}}\n</style>'

def render_admin_header(st, logo_uri):
    st.html(stylesheet_html() + ADMIN_CSS)
    st.markdown('<header class="bui-admin-header bunseki-ui"><img class="bui-admin-logo" src="' + escape(logo_uri, quote=True) + '" alt="BunsekiChat">' + icon_container("admin") + '<h1>Administración BunsekiChat</h1><p>Herramientas administrativas, seguimiento académico y reportes.</p></header>', unsafe_allow_html=True)
